		await searchInput.fill("test");
		// Close and reopen
		await screen.rerender(
			<Wrapper>
				<SectionPickerModal open={false} onOpenChange={onOpenChange} onSelect={vi.fn()} />
			</Wrapper>,
		);
		await screen.rerender(
			<Wrapper>
				<SectionPickerModal open={true} onOpenChange={onOpenChange} onSelect={vi.fn()} />
