it("should update sort_order for reordering", async () => {
				const ids = [ulid(), ulid(), ulid()];

				await db
					.insertInto("_emdash_widgets")
					.values([
						{
							id: ids[0],
							area_id: areaId,
							sort_order: 0,
							type: "content" as WidgetType,
							title: "A",
							content: null,
							menu_name: null,
							component_id: null,
							component_props: null,
						},
						{
							id: ids[1],
							area_id: areaId,
							sort_order: 1,
							type: "content" as WidgetType,
							title: "B",
							content: null,
							menu_name: null,
							component_id: null,
							component_props: null,
						},
						{
							id: ids[2],
							area_id: areaId,
							sort_order: 2,
							type: "content" as WidgetType,
							title: "C",
							content: null,
							menu_name: null,
							component_id: null,
							component_props: null,
						},
					])
					.execute();

				// Reorder: C (was 2) -> 0, A (was 0) -> 1, B (was 1) -> 2
				const newOrder = [ids[2], ids[0], ids[1]];
				for (let i = 0; i < newOrder.length; i++) {
					await db
						.updateTable("_emdash_widgets")
						.set({ sort_order: i })
						.where("id", "=", newOrder[i])
						.execute();
				}

				const widgets = await db
					.selectFrom("_emdash_widgets")
					.selectAll()
					.where("area_id", "=", areaId)
					.orderBy("sort_order", "asc")
					.execute();

				expect(widgets[0].title).toBe("C");
				expect(widgets[1].title).toBe("A");
				expect(widgets[2].title).toBe("B");
			})

